use crate::loader::{AnalysisGraph, EdgeKind};
use algorithms::graph::bellman_ford_gpu::bellman_ford_gpu;
use algorithms::graph::csr::Csr;
use algorithms::graph::depth_gpu::longest_path_depth_gpu;
use algorithms::graph::topological_sort_gpu::topological_sort_gpu;
use serde::Serialize;
use std::collections::BTreeMap;

#[derive(Debug, Serialize)]
pub struct AnomalyReport {
    pub depth_outliers: Vec<u32>,
    pub topo_missing: Vec<u32>,
    pub bellman_dist: Vec<u64>,
}

pub fn analyze_anomalies(graph: &AnalysisGraph) -> AnomalyReport {
    let flow = build_kind_csr(graph, EdgeKind::Flow);
    let depth = longest_path_depth_gpu(&flow);
    let (means, stds) = depth_stats(graph, &depth);
    let mut depth_outliers = Vec::new();
    for (idx, d) in depth.iter().enumerate() {
        let kind = graph.nodes[idx].kind;
        if let Some((mu, sigma)) = means.get(&kind).zip(stds.get(&kind)) {
            if *sigma > 0.0 && (*d as f64 - *mu).abs() > 3.0 * *sigma {
                depth_outliers.push(graph.nodes[idx].id);
            }
        }
    }

    let order = topological_sort_gpu(&flow);
    let mut seen = vec![false; flow.vertex_count()];
    for &v in &order {
        if v < seen.len() {
            seen[v] = true;
        }
    }
    let mut topo_missing = Vec::new();
    for (idx, ok) in seen.iter().enumerate() {
        if !*ok {
            topo_missing.push(graph.nodes[idx].id);
        }
    }

    let error_edges = edge_list_with_weights(graph, EdgeKind::ErrorToFunction);
    let bellman_dist = bellman_ford_gpu(graph.nodes.len(), &error_edges, 0).unwrap_or_default();

    AnomalyReport {
        depth_outliers,
        topo_missing,
        bellman_dist,
    }
}

fn map_id(graph: &AnalysisGraph, id: u32) -> Option<usize> {
    graph.id_to_index.get(&id).copied()
}

fn build_kind_csr(graph: &AnalysisGraph, kind: EdgeKind) -> Csr {
    let mut adj = vec![Vec::new(); graph.nodes.len()];
    for e in &graph.edges {
        if e.kind == kind {
            if let (Some(src), Some(dst)) = (map_id(graph, e.src), map_id(graph, e.dst)) {
                adj[src].push(dst);
            }
        }
    }
    Csr::from_adj(&adj)
}

fn depth_stats(graph: &AnalysisGraph, depth: &[i32]) -> (BTreeMap<crate::loader::NodeKind, f64>, BTreeMap<crate::loader::NodeKind, f64>) {
    let mut sums: BTreeMap<crate::loader::NodeKind, f64> = BTreeMap::new();
    let mut counts: BTreeMap<crate::loader::NodeKind, f64> = BTreeMap::new();
    for (idx, d) in depth.iter().enumerate() {
        let kind = graph.nodes[idx].kind;
        *sums.entry(kind).or_insert(0.0) += *d as f64;
        *counts.entry(kind).or_insert(0.0) += 1.0;
    }
    let mut means = BTreeMap::new();
    for (k, sum) in &sums {
        let c = counts.get(k).copied().unwrap_or(1.0);
        means.insert(*k, sum / c);
    }
    let mut var = BTreeMap::new();
    for (idx, d) in depth.iter().enumerate() {
        let kind = graph.nodes[idx].kind;
        let mu = means.get(&kind).copied().unwrap_or(0.0);
        let v = (*d as f64 - mu) * (*d as f64 - mu);
        *var.entry(kind).or_insert(0.0) += v;
    }
    let mut stds = BTreeMap::new();
    for (k, v) in &var {
        let c = counts.get(k).copied().unwrap_or(1.0);
        stds.insert(*k, (v / c).sqrt());
    }
    (means, stds)
}

fn edge_list_with_weights(graph: &AnalysisGraph, kind: EdgeKind) -> Vec<(usize, usize, u64)> {
    let mut edges = Vec::new();
    let rank = error_rank(graph);
    for e in &graph.edges {
        if e.kind == kind {
            let w = rank.get(&e.dst).copied().unwrap_or(1);
            if let (Some(src), Some(dst)) = (map_id(graph, e.src), map_id(graph, e.dst)) {
                edges.push((src, dst, w));
            }
        }
    }
    edges
}

fn error_rank(graph: &AnalysisGraph) -> BTreeMap<u32, u64> {
    let mut rank = BTreeMap::new();
    for e in &graph.edges {
        if e.kind == EdgeKind::ErrorToFunction {
            *rank.entry(e.dst).or_insert(0) += 1;
        }
    }
    rank
}

use crate::loader::{AnalysisGraph, EdgeKind, NodeKind};
use anyhow::{anyhow, Result};
use algorithms::graph::reachability::reachability_batched_gpu;
use algorithms::graph::csr::Csr;
use algorithms::graph::feature_gpu::edge_kind_histogram_gpu;
#[cfg(feature = "cuda")]
use algorithms::numerical::gpu::cosine_distance_gpu;
use serde::Serialize;

#[cfg(not(feature = "cuda"))]
compile_error!("analysis-engine duplicates requires feature \"cuda\"");

#[derive(Debug, Serialize)]
pub struct DuplicatePair {
    pub left: u32,
    pub right: u32,
    pub distance: f32,
    pub reachable: bool,
}

#[derive(Debug, Serialize)]
pub struct DuplicateReport {
    pub epsilon: f32,
    pub pairs: Vec<DuplicatePair>,
}

pub fn find_duplicates(graph: &AnalysisGraph, epsilon: f32) -> Result<DuplicateReport> {
    let kind_count = graph.edge_kinds.len().max(1);
    if kind_count > u8::MAX as usize {
        return Err(anyhow!("edge kind count exceeds u8 limit"));
    }
    let (csr, edge_kinds) = build_csr_with_kinds(graph)?;
    let counts = edge_kind_histogram_gpu(&csr, &edge_kinds, kind_count);

    let call_csr = build_kind_csr(graph, EdgeKind::Call);
    let rev_csr = reverse_csr(&call_csr);
    let candidates: Vec<usize> = graph
        .nodes
        .iter()
        .enumerate()
        .filter(|(_, n)| matches!(n.kind, NodeKind::Function | NodeKind::Method))
        .map(|(i, _)| i)
        .collect();

    let m = candidates.len();
    let mut phi_flat = vec![0.0f32; m * kind_count];
    for (ci, &node_idx) in candidates.iter().enumerate() {
        let denom = (csr.row_ptr[node_idx + 1] - csr.row_ptr[node_idx]) as f32 + 1.0;
        let base = node_idx * kind_count;
        for k in 0..kind_count {
            phi_flat[ci * kind_count + k] = counts[base + k] as f32 / denom;
        }
    }

    let dist_matrix = cosine_distance_gpu(&phi_flat, m, kind_count);

    let ancestors = reachability_batched_gpu(&rev_csr, &candidates);

    let mut pairs = Vec::new();
    for i in 0..candidates.len() {
        for j in (i + 1)..candidates.len() {
            let dist = dist_matrix[i * m + j];
            if dist < epsilon {
                let a = candidates[i];
                let b = candidates[j];
                let reachable = ancestors[i].iter().zip(ancestors[j].iter()).any(|(x, y)| *x && *y);
                pairs.push(DuplicatePair {
                    left: graph.nodes[a].id,
                    right: graph.nodes[b].id,
                    distance: dist,
                    reachable,
                });
            }
        }
    }

    Ok(DuplicateReport { epsilon, pairs })
}

fn edge_kind_index(graph: &AnalysisGraph, kind: EdgeKind) -> Option<usize> {
    graph.edge_kinds.iter().position(|k| *k == kind)
}

fn build_id_index(graph: &AnalysisGraph) -> Result<Vec<usize>> {
    let max_id = graph.nodes.iter().map(|n| n.id as usize).max().unwrap_or(0);
    let mut id_to_index = vec![usize::MAX; max_id + 1];
    for (idx, node) in graph.nodes.iter().enumerate() {
        let slot = &mut id_to_index[node.id as usize];
        if *slot != usize::MAX {
            return Err(anyhow!("duplicate node id {}", node.id));
        }
        *slot = idx;
    }
    Ok(id_to_index)
}

fn map_id(id_to_index: &[usize], id: u32) -> Option<usize> {
    let idx = id as usize;
    if idx >= id_to_index.len() || id_to_index[idx] == usize::MAX {
        return None;
    }
    Some(id_to_index[idx])
}

fn build_csr_with_kinds(graph: &AnalysisGraph) -> Result<(Csr, Vec<u8>)> {
    let id_to_index = build_id_index(graph)?;
    let mut adj: Vec<Vec<(usize, u8)>> = vec![Vec::new(); graph.nodes.len()];
    for e in &graph.edges {
        let idx = edge_kind_index(graph, e.kind).ok_or_else(|| anyhow!("missing edge kind index"))?;
        let src = map_id(&id_to_index, e.src);
        let dst = map_id(&id_to_index, e.dst);
        if let (Some(src), Some(dst)) = (src, dst) {
            adj[src].push((dst, idx as u8));
        }
    }
    let mut row_ptr = Vec::with_capacity(adj.len() + 1);
    let mut col_idx = Vec::new();
    let mut edge_kind = Vec::new();
    row_ptr.push(0i32);
    for neighbours in adj {
        for (dst, kind) in neighbours {
            col_idx.push(dst as i32);
            edge_kind.push(kind);
        }
        row_ptr.push(col_idx.len() as i32);
    }
    Ok((Csr { row_ptr, col_idx }, edge_kind))
}

fn build_kind_csr(graph: &AnalysisGraph, kind: EdgeKind) -> Csr {
    let id_to_index = build_id_index(graph).expect("invalid node ids");
    let mut adj = vec![Vec::new(); graph.nodes.len()];
    for e in &graph.edges {
        if e.kind == kind {
            let src = map_id(&id_to_index, e.src);
            let dst = map_id(&id_to_index, e.dst);
            if let (Some(src), Some(dst)) = (src, dst) {
                adj[src].push(dst);
            }
        }
    }
    Csr::from_adj(&adj)
}

fn reverse_csr(csr: &Csr) -> Csr {
    let mut adj = vec![Vec::new(); csr.vertex_count()];
    for u in 0..csr.vertex_count() {
        for &v in csr.neighbours(u) {
            adj[v as usize].push(u);
        }
    }
    Csr::from_adj(&adj)
}

use anyhow::Result;
