}

use crate::loader::{AnalysisGraph, EdgeKind};
use algorithms::control_flow::gpu::{dominators_gpu, reaching_definitions_gpu};
use algorithms::graph::csr::Csr;
use algorithms::graph::model_checking::model_check_gpu;
use serde::Serialize;

#[derive(Debug, Serialize)]
pub struct InvariantReport {
    pub dominator_words: usize,
    pub reaching_defs_words: usize,
    pub model_check_ok: bool,
}

pub fn analyze_invariants(graph: &AnalysisGraph) -> InvariantReport {
    let flow = build_kind_csr(graph, EdgeKind::Flow);
    let pred = reverse_csr(&flow);
    let node_count = flow.vertex_count();

    let dom = dominators_gpu(&pred, 0, node_count);
    let dominator_words = dom.len();

    let def_count = node_count.max(1);
    let words = (def_count + 63) / 64;
    let r#gen = vec![0u64; node_count * words];
    let kill = vec![0u64; node_count * words];
    let reaching = reaching_definitions_gpu(&pred, node_count, def_count, &r#gen, &kill);
    let reaching_defs_words = reaching.len();

    let invariant_mask = vec![1u8; node_count];
    let model_check_ok = model_check_gpu(&flow, &[0], &invariant_mask);

    InvariantReport {
        dominator_words,
        reaching_defs_words,
        model_check_ok,
    }
}

fn map_id(graph: &AnalysisGraph, id: u32) -> Option<usize> {
    graph.id_to_index.get(&id).copied()
}

fn build_kind_csr(graph: &AnalysisGraph, kind: EdgeKind) -> Csr {
    let mut adj = vec![Vec::new(); graph.nodes.len()];
    for e in &graph.edges {
        if e.kind == kind {
            if let (Some(src), Some(dst)) = (map_id(graph, e.src), map_id(graph, e.dst)) {
                adj[src].push(dst);
            }
        }
    }
    Csr::from_adj(&adj)
}

fn reverse_csr(csr: &Csr) -> Csr {
    let mut adj = vec![Vec::new(); csr.vertex_count()];
    for u in 0..csr.vertex_count() {
        for &v in csr.neighbours(u) {
            adj[v as usize].push(u);
        }
    }
    Csr::from_adj(&adj)
}

use anyhow::{anyhow, Result};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::collections::HashMap;
use std::fs;
use std::io::Read;
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
pub enum NodeKind {
    Function,
    Method,
    Struct,
    Enum,
    Trait,
    Impl,
    Field,
    Param,
    Variable,
    Module,
    Type,
    BasicBlock,
    CallSite,
    Error,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum EdgeKind {
    HasField,
    HasMethod,
    HasBlock,
    HasParam,
    Imports,
    Flow,
    Call,
    Return,
    Unwind,
    Implements,
    UsesType,
    Bounds,
    Assign,
    Propagates,
    ArgToParam,
    Returns,
    ErrorToFunction,
    ErrorToBlock,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Node {
    pub id: u32,
    pub kind: NodeKind,
    pub symbol: String,
    pub file: String,
    pub line: u32,
    pub column: u32,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Edge {
    pub src: u32,
    pub dst: u32,
    pub kind: EdgeKind,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Metadata {
    pub project: String,
    pub node_count: u32,
    pub edge_count: u32,
    pub generated_by: String,
}

#[derive(Debug, Clone)]
pub struct AnalysisGraph {
    pub nodes: Vec<Node>,
    pub edges: Vec<Edge>,
    pub row_ptr: Vec<u32>,
    pub col_idx: Vec<u32>,
    pub repair_surface: Value,
    pub errors: Value,
    pub metadata: Metadata,
    pub node_kinds: Vec<NodeKind>,
    pub edge_kinds: Vec<EdgeKind>,
    pub id_to_index: HashMap<u32, usize>,
}

pub fn load_dir(dir: &Path) -> Result<AnalysisGraph> {
    let nodes = read_nodes_csv(dir.join("nodes.csv"))?;
    let edges = read_edges_csv(dir.join("edges.csv"))?;
    let row_ptr = read_bin_u32(dir.join("csr_row_ptr.bin"))?;
    let col_idx = read_bin_u32(dir.join("csr_col_idx.bin"))?;
    let repair_surface = read_json(dir.join("repair_surface.json"));
    let errors = read_json(dir.join("errors.json"));
    let metadata = read_metadata(dir.join("metadata.json"))?;
    let node_kinds = read_node_kinds(dir.join("node_kinds.txt"))?;
    let edge_kinds = read_edge_kinds(dir.join("edge_kinds.txt"))?;

    let id_to_index: HashMap<u32, usize> = nodes.iter().enumerate().map(|(i, n)| (n.id, i)).collect();
    Ok(AnalysisGraph {
        nodes,
        edges,
        row_ptr,
        col_idx,
        repair_surface,
        errors,
        metadata,
        node_kinds,
        edge_kinds,
        id_to_index,
    })
}

fn read_nodes_csv(path: PathBuf) -> Result<Vec<Node>> {
    let content = fs::read_to_string(path)?;
    let mut nodes = Vec::new();
    for (idx, line) in content.lines().enumerate() {
        if idx == 0 || line.trim().is_empty() {
            continue;
        }
        let parts: Vec<&str> = line.split(',').collect();
        if parts.len() < 6 {
            return Err(anyhow!("invalid nodes.csv line"));
        }
        let id = match parts[0].parse::<u32>() {
            Ok(v) => v,
            Err(_) => continue,
        };
        let kind = match parse_node_kind(parts[1]) {
            Ok(v) => v,
            Err(_) => continue,
        };
        let line_no = match parts[parts.len() - 2].parse::<u32>() {
            Ok(v) => v,
            Err(_) => continue,
        };
        let col = match parts[parts.len() - 1].parse::<u32>() {
            Ok(v) => v,
            Err(_) => continue,
        };
        let file = parts[parts.len() - 3].to_string();
        let symbol = parts[2..parts.len() - 3].join(",");
        nodes.push(Node {
            id,
            kind,
            symbol,
            file,
            line: line_no,
            column: col,
        });
    }
    Ok(nodes)
}

fn read_edges_csv(path: PathBuf) -> Result<Vec<Edge>> {
    let content = fs::read_to_string(path)?;
    let mut edges = Vec::new();
    for (idx, line) in content.lines().enumerate() {
        if idx == 0 || line.trim().is_empty() {
            continue;
        }
        let parts: Vec<&str> = line.split(',').collect();
        if parts.len() < 3 {
            return Err(anyhow!("invalid edges.csv line"));
        }
        let src = match parts[0].parse::<u32>() {
            Ok(v) => v,
            Err(_) => continue,
        };
        let dst = match parts[1].parse::<u32>() {
            Ok(v) => v,
            Err(_) => continue,
        };
        let kind = match parse_edge_kind(parts[2]) {
            Ok(v) => v,
            Err(_) => continue,
        };
        edges.push(Edge { src, dst, kind });
    }
    Ok(edges)
}

fn read_bin_u32(path: PathBuf) -> Result<Vec<u32>> {
    let mut file = fs::File::open(path)?;
    let mut bytes = Vec::new();
    file.read_to_end(&mut bytes)?;
    if bytes.len() % 4 != 0 {
        return Err(anyhow!("invalid u32 binary length"));
    }
    let mut out = Vec::with_capacity(bytes.len() / 4);
    for chunk in bytes.chunks_exact(4) {
        out.push(u32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]));
    }
    Ok(out)
}

fn read_json(path: PathBuf) -> Value {
    fs::read_to_string(path).ok().and_then(|s| serde_json::from_str(&s).ok()).unwrap_or(Value::Null)
}

fn read_metadata(path: PathBuf) -> Result<Metadata> {
    let content = fs::read_to_string(path)?;
    Ok(serde_json::from_str(&content)?)
}

fn read_node_kinds(path: PathBuf) -> Result<Vec<NodeKind>> {
    let content = fs::read_to_string(path)?;
    let mut out = Vec::new();
    for line in content.lines() {
        let kind = parse_node_kind(line)?;
        out.push(kind);
    }
    Ok(out)
}

fn read_edge_kinds(path: PathBuf) -> Result<Vec<EdgeKind>> {
    let content = fs::read_to_string(path)?;
    let mut out = Vec::new();
    for line in content.lines() {
        let kind = parse_edge_kind(line)?;
        out.push(kind);
    }
    Ok(out)
}

fn parse_node_kind(raw: &str) -> Result<NodeKind> {
    match raw {
        "FUNCTION" => Ok(NodeKind::Function),
        "METHOD" => Ok(NodeKind::Method),
        "STRUCT" => Ok(NodeKind::Struct),
        "ENUM" => Ok(NodeKind::Enum),
        "TRAIT" => Ok(NodeKind::Trait),
        "IMPL" => Ok(NodeKind::Impl),
        "FIELD" => Ok(NodeKind::Field),
        "PARAM" => Ok(NodeKind::Param),
        "VARIABLE" => Ok(NodeKind::Variable),
        "MODULE" => Ok(NodeKind::Module),
        "TYPE" => Ok(NodeKind::Type),
        "BASIC_BLOCK" => Ok(NodeKind::BasicBlock),
        "CALL_SITE" => Ok(NodeKind::CallSite),
        "ERROR" => Ok(NodeKind::Error),
        _ => Err(anyhow!("unknown node kind")),
    }
}

fn parse_edge_kind(raw: &str) -> Result<EdgeKind> {
    match raw {
        "HAS_FIELD" => Ok(EdgeKind::HasField),
        "HAS_METHOD" => Ok(EdgeKind::HasMethod),
        "HAS_BLOCK" => Ok(EdgeKind::HasBlock),
        "HAS_PARAM" => Ok(EdgeKind::HasParam),
        "IMPORTS" => Ok(EdgeKind::Imports),
        "FLOW" => Ok(EdgeKind::Flow),
        "CALL" => Ok(EdgeKind::Call),
        "RETURN" => Ok(EdgeKind::Return),
        "UNWIND" => Ok(EdgeKind::Unwind),
        "IMPLEMENTS" => Ok(EdgeKind::Implements),
        "USES_TYPE" => Ok(EdgeKind::UsesType),
        "BOUNDS" => Ok(EdgeKind::Bounds),
        "ASSIGN" => Ok(EdgeKind::Assign),
        "PROPAGATES" => Ok(EdgeKind::Propagates),
        "ARG_TO_PARAM" => Ok(EdgeKind::ArgToParam),
        "RETURNS" => Ok(EdgeKind::Returns),
        "ERROR_TO_FUNCTION" => Ok(EdgeKind::ErrorToFunction),
        "ERROR_TO_BLOCK" => Ok(EdgeKind::ErrorToBlock),
        _ => Err(anyhow!("unknown edge kind")),
    }
}

use crate::duplicates::DuplicateReport;
use crate::loader::{AnalysisGraph, EdgeKind};
use algorithms::graph::csr::Csr;
use algorithms::graph::reachability::reachability_gpu;
use algorithms::graph::scc_gpu::scc_gpu;
use algorithms::graph::scheduler_gpu::{deadlock_gpu, pack_ready_priority, ready_mask_gpu};
use serde::Serialize;
use std::time::Instant;

#[derive(Debug, Serialize)]
pub struct RefactoringReport {
    pub scc_count: usize,
    pub recursive_clusters: usize,
    pub ready_count: i32,
    pub deadlock: bool,
    pub duplicates: usize,
    pub type_reachable: usize,
}

pub fn analyze_refactoring(graph: &AnalysisGraph, duplicates: &DuplicateReport) -> RefactoringReport {
    let t0 = Instant::now();
    let call = build_kind_csr(graph, EdgeKind::Call);
    let t_call = t0.elapsed();

    let t1 = Instant::now();
    let sccs = scc_gpu(&call);
    let t_scc = t1.elapsed();
    let recursive_clusters = sccs.iter().filter(|c| c.len() > 1).count();

    let t2 = Instant::now();
    let (deps_offset, deps_flat) = build_deps(&call);
    let status = vec![0u8; call.vertex_count()];
    let (ready_mask, ready_count, _completed) = ready_mask_gpu(&status, &deps_offset, &deps_flat);
    let priorities = vec![1u16; ready_mask.len()];
    let _keys = pack_ready_priority(&ready_mask, &priorities);
    let deadlock = deadlock_gpu(&status, &deps_offset, &deps_flat);
    let t_sched = t2.elapsed();

    let t3 = Instant::now();
    let uses = build_kind_csr(graph, EdgeKind::UsesType);
    let mut type_reachable = 0usize;
    for pair in &duplicates.pairs {
        if let (Some(src), Some(dst)) = (map_id(graph, pair.left), map_id(graph, pair.right)) {
            let reached = reachability_gpu(&uses, &[src]);
            if reached.get(dst).copied().unwrap_or(false) {
                type_reachable += 1;
            }
        }
    }
    let t_types = t3.elapsed();

    eprintln!(
        "refactoring timings: call_csr={:?} scc={:?} schedule={:?} uses+reachability={:?}",
        t_call, t_scc, t_sched, t_types
    );

    RefactoringReport {
        scc_count: sccs.len(),
        recursive_clusters,
        ready_count,
        deadlock,
        duplicates: duplicates.pairs.len(),
        type_reachable,
    }
}

fn map_id(graph: &AnalysisGraph, id: u32) -> Option<usize> {
    graph.id_to_index.get(&id).copied()
}

fn build_kind_csr(graph: &AnalysisGraph, kind: EdgeKind) -> Csr {
    let mut adj = vec![Vec::new(); graph.nodes.len()];
    for e in &graph.edges {
        if e.kind == kind {
            if let (Some(src), Some(dst)) = (map_id(graph, e.src), map_id(graph, e.dst)) {
                adj[src].push(dst);
            }
        }
    }
    Csr::from_adj(&adj)
}

fn build_deps(csr: &Csr) -> (Vec<i32>, Vec<i32>) {
    let mut offset = Vec::with_capacity(csr.vertex_count() + 1);
    let mut flat = Vec::with_capacity(csr.edge_count());
    offset.push(0i32);
    for u in 0..csr.vertex_count() {
        for &v in csr.neighbours(u) {
            flat.push(v);
        }
        offset.push(flat.len() as i32);
    }
    (offset, flat)
}

