use crate::loader::{AnalysisGraph, EdgeKind, NodeKind};
use std::collections::HashMap;
use z3::ast::{Ast, Bool, BV};
use z3::Context;

pub struct EncodedGraph<'ctx> {
    ctx: &'ctx Context,
    pub bb: HashMap<u32, Bool<'ctx>>,
    pub var: HashMap<u32, BV<'ctx>>,
    pub err: HashMap<u32, Bool<'ctx>>,
    pub flow_imps: Vec<Bool<'ctx>>,
    pub assign_eqs: Vec<Bool<'ctx>>,
    pub prop_eqs: Vec<Bool<'ctx>>,
    pub err_imps: Vec<Bool<'ctx>>,
}

impl<'ctx> EncodedGraph<'ctx> {
    pub fn build(graph: &AnalysisGraph, ctx: &'ctx Context) -> Self {
        let mut bb = HashMap::new();
        let mut var = HashMap::new();
        let mut err = HashMap::new();

        for node in &graph.nodes {
            match node.kind {
                NodeKind::BasicBlock => {
                    bb.insert(node.id, Bool::new_const(ctx, format!("bb_{}", node.id)));
                }
                NodeKind::Variable | NodeKind::Param => {
                    var.insert(node.id, BV::new_const(ctx, format!("val_{}", node.id), 32));
                }
                NodeKind::Error => {
                    err.insert(node.id, Bool::new_const(ctx, format!("err_{}", node.id)));
                }
                _ => {}
            }
        }

        let mut flow_imps = Vec::new();
        let mut assign_eqs = Vec::new();
        let mut prop_eqs = Vec::new();
        let mut err_imps = Vec::new();

        for edge in &graph.edges {
            match edge.kind {
                EdgeKind::Flow => {
                    if let (Some(src), Some(dst)) = (bb.get(&edge.src), bb.get(&edge.dst)) {
                        flow_imps.push(src.implies(dst));
                    }
                }
                EdgeKind::Assign => {
                    if let (Some(src), Some(dst)) = (var.get(&edge.src), var.get(&edge.dst)) {
                        assign_eqs.push(dst._eq(src));
                    }
                }
                EdgeKind::Propagates => {
                    if let (Some(src), Some(dst)) = (var.get(&edge.src), var.get(&edge.dst)) {
                        prop_eqs.push(dst._eq(src));
                    }
                }
                EdgeKind::ErrorToBlock => {
                    if let (Some(block), Some(err_node)) = (bb.get(&edge.dst), err.get(&edge.src)) {
                        err_imps.push(block.implies(err_node));
                    }
                }
                _ => {}
            }
        }

        Self {
            ctx,
            bb,
            var,
            err,
            flow_imps,
            assign_eqs,
            prop_eqs,
            err_imps,
        }
    }

    pub fn build_scoped(graph: &AnalysisGraph, ctx: &'ctx Context, fn_id: u32) -> Self {
        let mut bb = HashMap::new();
        let mut var = HashMap::new();
        let mut err = HashMap::new();

        let mut block_ids = Vec::new();
        let mut block_set = std::collections::HashSet::new();
        for e in &graph.edges {
            if e.kind == EdgeKind::HasBlock && e.src == fn_id {
                if let Some(node) = graph.id_to_index.get(&e.dst).and_then(|&i| graph.nodes.get(i)) {
                    if node.kind == NodeKind::BasicBlock {
                        block_ids.push(node.id);
                        block_set.insert(node.id);
                    }
                }
            }
        }

        for id in &block_ids {
            bb.insert(*id, Bool::new_const(ctx, format!("bb_{}", id)));
        }
        for node in &graph.nodes {
            if matches!(node.kind, NodeKind::Variable | NodeKind::Param) {
                var.insert(node.id, BV::new_const(ctx, format!("val_{}", node.id), 32));
            }
            if node.kind == NodeKind::Error {
                err.insert(node.id, Bool::new_const(ctx, format!("err_{}", node.id)));
            }
        }

        let mut flow_imps = Vec::new();
        let mut assign_eqs = Vec::new();
        let mut prop_eqs = Vec::new();
        let mut err_imps = Vec::new();

        for edge in &graph.edges {
            match edge.kind {
                EdgeKind::Flow => {
                    if block_set.contains(&edge.src) && block_set.contains(&edge.dst) {
                        if let (Some(src), Some(dst)) = (bb.get(&edge.src), bb.get(&edge.dst)) {
                            flow_imps.push(src.implies(dst));
                        }
                    }
                }
                EdgeKind::Assign => {
                    if let (Some(src), Some(dst)) = (var.get(&edge.src), var.get(&edge.dst)) {
                        assign_eqs.push(dst._eq(src));
                    }
                }
                EdgeKind::Propagates => {
                    if let (Some(src), Some(dst)) = (var.get(&edge.src), var.get(&edge.dst)) {
                        prop_eqs.push(dst._eq(src));
                    }
                }
                EdgeKind::ErrorToBlock => {
                    if block_set.contains(&edge.dst) {
                        if let (Some(block), Some(err_node)) = (bb.get(&edge.dst), err.get(&edge.src)) {
                            err_imps.push(block.implies(err_node));
                        }
                    }
                }
                _ => {}
            }
        }

        Self {
            ctx,
            bb,
            var,
            err,
            flow_imps,
            assign_eqs,
            prop_eqs,
            err_imps,
        }
    }

    pub fn assert_all(&self, solver: &z3::Solver<'ctx>) {
        for imp in &self.flow_imps {
            solver.assert(imp);
        }
        for eq in &self.assign_eqs {
            solver.assert(eq);
        }
        for eq in &self.prop_eqs {
            solver.assert(eq);
        }
        for imp in &self.err_imps {
            solver.assert(imp);
        }
    }

    pub fn ctx(&self) -> &'ctx Context {
        self.ctx
    }
}

use crate::loader::{AnalysisGraph, NodeKind};
use crate::smt::cache::{equivalence_key, equivalence_graph_hash, CacheEntry, now_ts};
use crate::smt::encoder::EncodedGraph;
use serde::Serialize;
use serde_json::Value;
use std::collections::BTreeMap;
use z3::SatResult;
use z3::ast::Ast;

#[derive(Debug, Serialize)]
pub struct EquivalenceResult {
    pub kind: String,
    pub a: u32,
    pub b: u32,
    pub smt_equivalent: bool,
    pub distinguishing_input: Option<Value>,
}

pub fn check_equivalence(
    session: &crate::smt::SmtSession,
    graph: &AnalysisGraph,
    candidates: &Value,
) -> Vec<EquivalenceResult> {
    let mut results = Vec::new();
    let pairs = candidates.get("pairs").and_then(|v| v.as_array()).cloned().unwrap_or_default();

    let mut fn_prefix: BTreeMap<u32, String> = BTreeMap::new();
    for node in &graph.nodes {
        if matches!(node.kind, NodeKind::Function | NodeKind::Method) {
            let prefix = node.symbol.trim_end_matches("::fn").to_string();
            fn_prefix.insert(node.id, prefix);
        }
    }

    for pair in pairs {
        let a = pair.get("a").and_then(|v| v.as_u64()).unwrap_or(0) as u32;
        let b = pair.get("b").and_then(|v| v.as_u64()).unwrap_or(0) as u32;
        if a == 0 || b == 0 {
            continue;
        }

        let graph_hash = equivalence_graph_hash(graph, a, b);
        let key = equivalence_key(a, b, &graph_hash);
        if let Ok(cache) = session.cache().lock() {
            if let Some(entry) = cache.get(&key, &graph_hash) {
                let eq = entry.result == "unsat";
                results.push(EquivalenceResult {
                    kind: pair.get("kind").and_then(|v| v.as_str()).unwrap_or("unknown").to_string(),
                    a,
                    b,
                    smt_equivalent: eq,
                    distinguishing_input: entry.model,
                });
                continue;
            }
        }

        let vars_a = vars_for_function(graph, &fn_prefix, a);
        let vars_b = vars_for_function(graph, &fn_prefix, b);
        let params_a = params_for_function(graph, &fn_prefix, a);
        let params_b = params_for_function(graph, &fn_prefix, b);
        let returns_a = returns_for_function(graph, &fn_prefix, a);
        let returns_b = returns_for_function(graph, &fn_prefix, b);
        if vars_a.is_empty()
            || vars_b.is_empty()
            || vars_a.len() != vars_b.len()
            || params_a.len() != params_b.len()
            || returns_a.len() != returns_b.len()
        {
            results.push(EquivalenceResult {
                kind: pair.get("kind").and_then(|v| v.as_str()).unwrap_or("unknown").to_string(),
                a,
                b,
                smt_equivalent: false,
                distinguishing_input: None,
            });
            continue;
        }

        let encoded_a = EncodedGraph::build_scoped(graph, session.ctx(), a);
        let encoded_b = EncodedGraph::build_scoped(graph, session.ctx(), b);
        let solver = session.solver();
        encoded_a.assert_all(&solver);
        encoded_b.assert_all(&solver);
        solver.push();
        for (lhs, rhs) in params_a.iter().zip(params_b.iter()) {
            if let (Some(l), Some(r)) = (encoded_a.var.get(lhs), encoded_b.var.get(rhs)) {
                solver.assert(&l._eq(r));
            }
        }
        let mut output_diffs = Vec::new();
        for (lhs, rhs) in returns_a.iter().zip(returns_b.iter()) {
            if let (Some(l), Some(r)) = (encoded_a.var.get(lhs), encoded_b.var.get(rhs)) {
                output_diffs.push(l._eq(r).not());
            }
        }
        if output_diffs.is_empty() {
            solver.pop(1);
            results.push(EquivalenceResult {
                kind: pair.get("kind").and_then(|v| v.as_str()).unwrap_or("unknown").to_string(),
                a,
                b,
                smt_equivalent: false,
                distinguishing_input: None,
            });
            continue;
        }
        let diff_refs: Vec<&z3::ast::Bool<'_>> = output_diffs.iter().collect();
        solver.assert(&z3::ast::Bool::or(session.ctx(), &diff_refs));
        let verdict = match solver.check() {
            SatResult::Unsat => true,
            SatResult::Sat => false,
            SatResult::Unknown => false,
        };
        let distinguishing_input = if !verdict {
            let model = solver.get_model();
            model.map(|m| {
                let mut vals = BTreeMap::new();
                for (ra, rb) in returns_a.iter().zip(returns_b.iter()) {
                    if let (Some(l), Some(r)) = (encoded_a.var.get(ra), encoded_b.var.get(rb)) {
                        let lv = m.eval(l, true).and_then(|v| v.as_u64());
                        let rv = m.eval(r, true).and_then(|v| v.as_u64());
                        vals.insert(format!("val_{}", ra), lv.map(|v| v.to_string()).unwrap_or_default());
                        vals.insert(format!("val_{}", rb), rv.map(|v| v.to_string()).unwrap_or_default());
                    }
                }
                serde_json::to_value(vals).unwrap_or(Value::Null)
            })
        } else {
            None
        };
        if let Ok(mut cache) = session.cache().lock() {
            let entry = CacheEntry {
                result: if verdict { "unsat".to_string() } else { "sat".to_string() },
                model: distinguishing_input.clone(),
                graph_hash: graph_hash.clone(),
                timestamp: now_ts(),
            };
            cache.insert(key, entry);
        }
        results.push(EquivalenceResult {
            kind: pair.get("kind").and_then(|v| v.as_str()).unwrap_or("unknown").to_string(),
            a,
            b,
            smt_equivalent: verdict,
            distinguishing_input,
        });
        solver.pop(1);
    }
    results
}

fn vars_for_function(graph: &AnalysisGraph, prefixes: &BTreeMap<u32, String>, fn_id: u32) -> Vec<u32> {
    let Some(prefix) = prefixes.get(&fn_id) else {
        return Vec::new();
    };
    let mut vars: Vec<(String, u32)> = graph
        .nodes
        .iter()
        .filter(|n| matches!(n.kind, NodeKind::Variable | NodeKind::Param))
        .filter(|n| n.symbol.starts_with(prefix))
        .map(|n| (n.symbol.clone(), n.id))
        .collect();
    vars.sort_by(|a, b| a.0.cmp(&b.0));
    vars.into_iter().map(|(_, id)| id).collect()
}

fn params_for_function(graph: &AnalysisGraph, prefixes: &BTreeMap<u32, String>, fn_id: u32) -> Vec<u32> {
    let Some(prefix) = prefixes.get(&fn_id) else {
        return Vec::new();
    };
    let mut vars: Vec<(String, u32)> = graph
        .nodes
        .iter()
        .filter(|n| n.kind == NodeKind::Param)
        .filter(|n| n.symbol.starts_with(prefix))
        .map(|n| (n.symbol.clone(), n.id))
        .collect();
    vars.sort_by(|a, b| a.0.cmp(&b.0));
    vars.into_iter().map(|(_, id)| id).collect()
}

fn returns_for_function(graph: &AnalysisGraph, prefixes: &BTreeMap<u32, String>, fn_id: u32) -> Vec<u32> {
    let Some(prefix) = prefixes.get(&fn_id) else {
        return Vec::new();
    };
    let mut vars: Vec<(String, u32)> = graph
        .nodes
        .iter()
        .filter(|n| n.kind == NodeKind::Variable)
        .filter(|n| n.symbol.starts_with(prefix))
        .filter(|n| n.symbol.contains("::_0") || n.symbol.ends_with("::ret"))
        .map(|n| (n.symbol.clone(), n.id))
        .collect();
    vars.sort_by(|a, b| a.0.cmp(&b.0));
    vars.into_iter().map(|(_, id)| id).collect()
}

use crate::loader::AnalysisGraph;
use crate::smt::cache::{invariant_graph_hash, invariant_key, CacheEntry, now_ts};
use crate::smt::encoder::EncodedGraph;
use serde::Serialize;
use serde_json::{json, Value};
use z3::SatResult;
use z3::ast::Ast;

#[derive(Debug, Serialize)]
pub struct InvariantSmtResult {
    pub predicate: String,
    pub smt_verdict: String,
    pub counterexample: Option<Value>,
}

pub fn prove_invariants(
    session: &crate::smt::SmtSession,
    graph: &AnalysisGraph,
    invariants: &Value,
) -> Value {
    let encoded = EncodedGraph::build(graph, session.ctx());
    let mut out = invariants.clone();
    let mut results: Vec<InvariantSmtResult> = Vec::new();
    let candidate_graph = graph;

    let candidate_list = invariants
        .get("candidates")
        .and_then(|v| v.as_array())
        .cloned()
        .unwrap_or_default();

    if candidate_list.is_empty() {
        if let Some(obj) = out.as_object_mut() {
            obj.insert("smt_verdicts".to_string(), serde_json::to_value(results).unwrap_or(Value::Null));
        }
        return out;
    }

    let solver = session.solver();
    solver.push();
    encoded.assert_all(&solver);

    for cand in candidate_list {
        let pred = cand.get("predicate").and_then(|v| v.as_str()).unwrap_or("unknown");
        let graph_hash = invariant_graph_hash(candidate_graph, &cand);
        let key = invariant_key(pred, &graph_hash);
        if let Ok(cache) = session.cache().lock() {
            if let Some(entry) = cache.get(&key, &graph_hash) {
                results.push(InvariantSmtResult {
                    predicate: pred.to_string(),
                    smt_verdict: entry.result,
                    counterexample: entry.model,
                });
                continue;
            }
        }
        solver.push();
        let mut asserted = false;
        if let Some(kind) = cand.get("kind").and_then(|v| v.as_str()) {
            match kind {
                "bb_true" => {
                    if let Some(id) = cand.get("block_id").and_then(|v| v.as_u64()) {
                        if let Some(bb) = encoded.bb.get(&(id as u32)) {
                            solver.assert(&bb.not());
                            asserted = true;
                        }
                    }
                }
                "err_unreachable" => {
                    if let Some(id) = cand.get("error_id").and_then(|v| v.as_u64()) {
                        if let Some(err) = encoded.err.get(&(id as u32)) {
                            solver.assert(err);
                            asserted = true;
                        }
                    }
                }
                "var_eq" => {
                    let lhs = cand.get("lhs").and_then(|v| v.as_u64()).unwrap_or(0) as u32;
                    let rhs = cand.get("rhs").and_then(|v| v.as_u64()).unwrap_or(0) as u32;
                    if let (Some(l), Some(r)) = (encoded.var.get(&lhs), encoded.var.get(&rhs)) {
                        solver.assert(&l._eq(r).not());
                        asserted = true;
                    }
                }
                _ => {}
            }
        }
        if !asserted {
            let neg = z3::ast::Bool::new_const(encoded.ctx(), format!("neg_{}", pred));
            solver.assert(&neg);
        }
        let verdict = match solver.check() {
            SatResult::Unsat => "proven",
            SatResult::Sat => "violated",
            SatResult::Unknown => "unverified",
        };
        let counterexample = if verdict == "violated" { Some(json!({})) } else { None };
        if let Ok(mut cache) = session.cache().lock() {
            let entry = CacheEntry {
                result: verdict.to_string(),
                model: counterexample.clone(),
                graph_hash,
                timestamp: now_ts(),
            };
            cache.insert(key, entry);
        }
        solver.pop(1);
        results.push(InvariantSmtResult {
            predicate: pred.to_string(),
            smt_verdict: verdict.to_string(),
            counterexample,
        });
    }
    solver.pop(1);

    if let Some(obj) = out.as_object_mut() {
        obj.insert("smt_verdicts".to_string(), serde_json::to_value(results).unwrap_or(Value::Null));
    }
    out
}

use crate::loader::{AnalysisGraph, EdgeKind, NodeKind};
use crate::smt::encoder::EncodedGraph;
use crate::smt::cache::{reachability_key, function_graph_hash, CacheEntry, now_ts};
use algorithms::graph::csr::Csr;
use algorithms::graph::reachability::reachability_gpu;
use serde::Serialize;
use serde_json::Value;
use std::collections::BTreeMap;
use z3::SatResult;

#[derive(Debug, Serialize)]
pub struct SmtReachabilityEntry {
    pub node_id: u32,
    pub smt_reachable: bool,
    pub smt_path_condition: BTreeMap<String, bool>,
}

pub fn check_repair_surface(
    session: &crate::smt::SmtSession,
    graph: &AnalysisGraph,
    repair_surface: &Value,
) -> Vec<SmtReachabilityEntry> {
    let mut out = Vec::new();
    let top_k = repair_surface
        .get("top_k")
        .and_then(|v| v.as_array())
        .cloned()
        .unwrap_or_default();
    for entry in top_k {
        let node_id = entry.get("node_id").and_then(|v| v.as_u64()).unwrap_or(0) as u32;
        if node_id == 0 {
            continue;
        }
        let (reachable, path) = check_function_errors(session, graph, node_id);
        out.push(SmtReachabilityEntry {
            node_id,
            smt_reachable: reachable,
            smt_path_condition: path,
        });
    }
    out
}

fn check_function_errors(
    session: &crate::smt::SmtSession,
    graph: &AnalysisGraph,
    fn_id: u32,
) -> (bool, BTreeMap<String, bool>) {
    let encoded = EncodedGraph::build_scoped(graph, session.ctx(), fn_id);
    let entry_block = entry_block_for_function(graph, fn_id);
    let entry_block = match entry_block.and_then(|id| encoded.bb.get(&id)) {
        Some(bb) => bb.clone(),
        None => return (false, BTreeMap::new()),
    };

    let error_nodes: Vec<u32> = graph
        .edges
        .iter()
        .filter(|e| e.kind == EdgeKind::ErrorToFunction && e.dst == fn_id)
        .map(|e| e.src)
        .collect();
    if error_nodes.is_empty() {
        return (false, BTreeMap::new());
    }

    let reachable_blocks = reachable_blocks_for_function(graph, fn_id);

    let graph_hash = function_graph_hash(graph, fn_id);
    let solver = session.solver();
    solver.push();
    encoded.assert_all(&solver);
    solver.assert(&entry_block);
    for err_id in error_nodes {
        if !error_structurally_reachable(graph, err_id, &reachable_blocks) {
            continue;
        }
        let key = reachability_key(fn_id, err_id, &graph_hash);
        if let Ok(cache) = session.cache().lock() {
            if let Some(entry) = cache.get(&key, &graph_hash) {
                if entry.result == "sat" {
                    let path = entry.model.and_then(|v| serde_json::from_value(v).ok()).unwrap_or_default();
                    solver.pop(1);
                    return (true, path);
                }
                if entry.result == "unsat" || entry.result == "unknown" {
                    continue;
                }
            }
        }
        let err = match encoded.err.get(&err_id) {
            Some(e) => e.clone(),
            None => continue,
        };
        solver.push();
        solver.assert(&err);
        let result = solver.check();
        match result {
            SatResult::Sat => {
                let model = solver.get_model();
                let mut path = BTreeMap::new();
                if let Some(model) = model {
                    for (id, bb) in &encoded.bb {
                        if let Some(val) = model.eval(bb, true).and_then(|v| v.as_bool()) {
                            path.insert(format!("bb_{}", id), val);
                        }
                    }
                }
                if let Ok(mut cache) = session.cache().lock() {
                    let entry = CacheEntry {
                        result: "sat".to_string(),
                        model: serde_json::to_value(&path).ok(),
                        graph_hash: graph_hash.clone(),
                        timestamp: now_ts(),
                    };
                    cache.insert(key, entry);
                }
                solver.pop(1);
                solver.pop(1);
                return (true, path);
            }
            SatResult::Unsat | SatResult::Unknown => {
                if let Ok(mut cache) = session.cache().lock() {
                    let entry = CacheEntry {
                        result: if matches!(result, SatResult::Unsat) { "unsat".to_string() } else { "unknown".to_string() },
                        model: None,
                        graph_hash: graph_hash.clone(),
                        timestamp: now_ts(),
                    };
                    cache.insert(key, entry);
                }
                solver.pop(1);
            }
        }
    }
    solver.pop(1);
    (false, BTreeMap::new())
}

fn entry_block_for_function(graph: &AnalysisGraph, fn_id: u32) -> Option<u32> {
    let mut blocks: Vec<&crate::loader::Node> = graph
        .edges
        .iter()
        .filter(|e| e.kind == EdgeKind::HasBlock && e.src == fn_id)
        .filter_map(|e| graph.id_to_index.get(&e.dst).and_then(|&i| graph.nodes.get(i)))
        .filter(|n| n.kind == NodeKind::BasicBlock)
        .collect();
    if blocks.is_empty() {
        return None;
    }
    blocks.sort_by_key(|n| n.symbol.clone());
    blocks.first().map(|n| n.id)
}

fn reachable_blocks_for_function(graph: &AnalysisGraph, fn_id: u32) -> BTreeMap<u32, bool> {
    let mut blocks: Vec<u32> = graph
        .edges
        .iter()
        .filter(|e| e.kind == EdgeKind::HasBlock && e.src == fn_id)
        .filter_map(|e| graph.id_to_index.get(&e.dst).and_then(|&i| graph.nodes.get(i)))
        .filter(|n| n.kind == NodeKind::BasicBlock)
        .map(|n| n.id)
        .collect();
    blocks.sort();
    if blocks.is_empty() {
        return BTreeMap::new();
    }

    let mut index: BTreeMap<u32, usize> = BTreeMap::new();
    for (i, id) in blocks.iter().enumerate() {
        index.insert(*id, i);
    }

    let mut adj = vec![Vec::new(); blocks.len()];
    for e in &graph.edges {
        if e.kind == EdgeKind::Flow {
            if let (Some(&u), Some(&v)) = (index.get(&e.src), index.get(&e.dst)) {
                adj[u].push(v);
            }
        }
    }
    let csr = Csr::from_adj(&adj);

    let entry_block = entry_block_for_function(graph, fn_id);
    let entry_idx = entry_block.and_then(|id| index.get(&id).copied());
    let mut reachable = BTreeMap::new();
    if let Some(root) = entry_idx {
        let mask = reachability_gpu(&csr, &[root]);
        for (i, id) in blocks.iter().enumerate() {
            reachable.insert(*id, mask.get(i).copied().unwrap_or(false));
        }
    } else {
        for id in blocks {
            reachable.insert(id, false);
        }
    }
    reachable
}

fn error_structurally_reachable(graph: &AnalysisGraph, err_id: u32, reachable_blocks: &BTreeMap<u32, bool>) -> bool {
    let mut has_block_edge = false;
    for e in &graph.edges {
        if e.kind == EdgeKind::ErrorToBlock && e.src == err_id {
            has_block_edge = true;
            if reachable_blocks.get(&e.dst).copied().unwrap_or(false) {
                return true;
            }
        }
    }
    if !has_block_edge {
        return true;
    }
    false
}

use crate::smt::reachability::SmtReachabilityEntry;
use serde::Serialize;
use serde_json::Value;
use std::collections::BTreeMap;

#[derive(Debug, Serialize)]
pub struct RepairSurfaceSmtEntry {
    pub node_id: u32,
    pub smt_reachable: bool,
    pub rank_smt: usize,
}

pub fn build_repair_surface_smt(repair_surface: &Value, reachability: &[SmtReachabilityEntry]) -> Value {
    let mut reach_map: BTreeMap<u32, bool> = BTreeMap::new();
    for entry in reachability {
        reach_map.insert(entry.node_id, entry.smt_reachable);
    }

    let top_k = repair_surface
        .get("top_k")
        .and_then(|v| v.as_array())
        .cloned()
        .unwrap_or_default();
    let mut out = Vec::new();
    for entry in top_k {
        let node_id = entry.get("node_id").and_then(|v| v.as_u64()).unwrap_or(0) as u32;
        if node_id == 0 {
            continue;
        }
        let error_count = entry.get("error_count").and_then(|v| v.as_u64()).unwrap_or(0) as usize;
        let smt_reachable = reach_map.get(&node_id).copied().unwrap_or(false);
        let rank_smt = if smt_reachable { error_count } else { 0 };
        out.push(RepairSurfaceSmtEntry {
            node_id,
            smt_reachable,
            rank_smt,
        });
    }
    serde_json::json!({
        "top_k": out,
        "count": out.len()
    })
}

use crate::loader::{AnalysisGraph, EdgeKind, NodeKind};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use sha2::{Digest, Sha256};
use std::collections::{HashMap, HashSet};
use std::fs;
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CacheEntry {
    pub result: String,
    pub model: Option<Value>,
    pub graph_hash: String,
    pub timestamp: u64,
}

#[derive(Debug, Default, Serialize, Deserialize)]
struct CacheFile {
    entries: HashMap<String, CacheEntry>,
}

pub struct ProofCache {
    path: PathBuf,
    entries: HashMap<String, CacheEntry>,
    dirty: bool,
}

impl ProofCache {
    pub fn new(path: PathBuf, clear: bool) -> Self {
        if clear {
            let _ = fs::remove_file(&path);
        }
        let entries = if !clear {
            load_cache(&path)
        } else {
            HashMap::new()
        };
        Self {
            path,
            entries,
            dirty: false,
        }
    }

    pub fn get(&self, key: &str, graph_hash: &str) -> Option<CacheEntry> {
        self.entries.get(key).and_then(|entry| {
            if entry.graph_hash == graph_hash {
                Some(entry.clone())
            } else {
                None
            }
        })
    }

    pub fn insert(&mut self, key: String, entry: CacheEntry) {
        self.entries.insert(key, entry);
        self.dirty = true;
    }
}

impl Drop for ProofCache {
    fn drop(&mut self) {
        if !self.dirty {
            return;
        }
        let payload = CacheFile {
            entries: self.entries.clone(),
        };
        if let Ok(text) = serde_json::to_string_pretty(&payload) {
            let _ = fs::write(&self.path, text);
        }
    }
}

fn load_cache(path: &Path) -> HashMap<String, CacheEntry> {
    let Ok(text) = fs::read_to_string(path) else {
        return HashMap::new();
    };
    serde_json::from_str::<CacheFile>(&text)
        .map(|f| f.entries)
        .unwrap_or_default()
}

pub fn reachability_key(fn_id: u32, err_id: u32, graph_hash: &str) -> String {
    hash_parts(&[&format!("reach:{fn_id}:{err_id}"), graph_hash])
}

pub fn invariant_key(predicate: &str, graph_hash: &str) -> String {
    hash_parts(&[&format!("inv:{predicate}"), graph_hash])
}

pub fn equivalence_key(a: u32, b: u32, graph_hash: &str) -> String {
    hash_parts(&[&format!("eq:{a}:{b}"), graph_hash])
}

pub fn now_ts() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

pub fn function_graph_hash(graph: &AnalysisGraph, fn_id: u32) -> String {
    let blocks = function_blocks(graph, fn_id);
    if blocks.is_empty() {
        return hash_parts(&[&format!("fn:{fn_id}")]);
    }
    let mut edges: Vec<String> = Vec::new();
    let block_set: HashSet<u32> = blocks.iter().copied().collect();
    for e in &graph.edges {
        match e.kind {
            EdgeKind::Flow => {
                if block_set.contains(&e.src) && block_set.contains(&e.dst) {
                    edges.push(format!("flow:{}->{}", e.src, e.dst));
                }
            }
            EdgeKind::ErrorToBlock => {
                if block_set.contains(&e.dst) {
                    edges.push(format!("err:{}->{}", e.src, e.dst));
                }
            }
            _ => {}
        }
    }
    edges.sort();
    let mut parts = Vec::new();
    parts.push(format!("fn:{fn_id}"));
    for b in blocks {
        parts.push(format!("bb:{b}"));
    }
    for e in edges {
        parts.push(e);
    }
    hash_parts(&parts.iter().map(|s| s.as_str()).collect::<Vec<_>>())
}

pub fn equivalence_graph_hash(graph: &AnalysisGraph, a: u32, b: u32) -> String {
    let ha = function_graph_hash(graph, a);
    let hb = function_graph_hash(graph, b);
    hash_parts(&[&ha, &hb])
}

pub fn invariant_graph_hash(graph: &AnalysisGraph, candidate: &Value) -> String {
    if let Some(fid) = candidate.get("function_id").and_then(|v| v.as_u64()) {
        return function_graph_hash(graph, fid as u32);
    }
    if let Some(bid) = candidate.get("block_id").and_then(|v| v.as_u64()) {
        if let Some(fid) = function_for_block(graph, bid as u32) {
            return function_graph_hash(graph, fid);
        }
    }
    hash_parts(&[&format!("graph:{}", graph.nodes.len())])
}

fn function_blocks(graph: &AnalysisGraph, fn_id: u32) -> Vec<u32> {
    let mut blocks = Vec::new();
    for e in &graph.edges {
        if e.kind == EdgeKind::HasBlock && e.src == fn_id {
            if let Some(node) = graph.id_to_index.get(&e.dst).and_then(|&i| graph.nodes.get(i)) {
                if node.kind == NodeKind::BasicBlock {
                    blocks.push(node.id);
                }
            }
        }
    }
    blocks.sort();
    blocks
}

fn function_for_block(graph: &AnalysisGraph, block_id: u32) -> Option<u32> {
    for e in &graph.edges {
        if e.kind == EdgeKind::HasBlock && e.dst == block_id {
            return Some(e.src);
        }
    }
    None
}

fn hash_parts(parts: &[&str]) -> String {
    let mut hasher = Sha256::new();
    for part in parts {
        hasher.update(part.as_bytes());
        hasher.update(&[0u8]);
    }
    let digest = hasher.finalize();
    hex::encode(digest)
}

use crate::loader::{Edge, EdgeKind, Metadata, Node, NodeKind};
use anyhow::{anyhow, Result};
use serde::Deserialize;
use serde_json::Value;
use std::collections::BTreeMap;
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};

#[derive(Debug, Deserialize)]
struct ErrorPayload {
    errors: Vec<Value>,
}

#[derive(Debug, Clone, serde::Serialize)]
pub struct RepairSurfaceEntry {
    pub node_id: u32,
    pub symbol: String,
    pub file: String,
    pub line: u32,
    pub error_count: usize,
}

pub fn augment_with_errors(output_dir: &Path, errors_json: &Path) -> Result<()> {
    if !errors_json.exists() {
        return Ok(());
    }
    let payload = fs::read_to_string(errors_json)?;
    let parsed: ErrorPayload = serde_json::from_str(&payload).unwrap_or(ErrorPayload { errors: Vec::new() });
    if parsed.errors.is_empty() {
        return Ok(());
    }

    let mut nodes = read_nodes_csv(output_dir.join("nodes.csv"))?;
    let mut edges = read_edges_csv(output_dir.join("edges.csv"))?;

    let mut next_id = nodes.iter().map(|n| n.id).max().unwrap_or(0).saturating_add(1);
    let mut added_errors: Vec<(u32, ErrorSpan)> = Vec::new();
    let mut synthetic_modules: BTreeMap<String, u32> = BTreeMap::new();

    for (idx, err) in parsed.errors.iter().enumerate() {
        let span = primary_span(err);
        let (file, line, column) = span
            .as_ref()
            .map(|s| (s.file.clone(), s.line_start, s.col_start))
            .unwrap_or_else(|| ("unknown".to_string(), 0, 0));
        let code = err.get("code").and_then(|c| c.get("code")).and_then(|v| v.as_str()).unwrap_or("unknown");
        let symbol = format!("error::{code}::{idx}");
        let node_id = next_id;
        next_id = next_id.saturating_add(1);
        nodes.push(Node {
            id: node_id,
            kind: NodeKind::Error,
            symbol,
            file,
            line,
            column,
        });
        if let Some(span) = span {
            added_errors.push((node_id, span));
        }
    }

    let mut edges_added = Vec::new();
    for (err_id, span) in &added_errors {
        let mut function_targets = find_nodes_at_span(&nodes, span, NodeKind::Function);
        function_targets.extend(find_nodes_at_span(&nodes, span, NodeKind::Method));

        let selected_fn = if function_targets.is_empty() {
            let file_key = normalize_file(&span.file);
            let nearest = find_nearest_node(&nodes, span, &[NodeKind::Function, NodeKind::Method])
                .or_else(|| find_nearest_node(&nodes, span, &[NodeKind::Module]))
                .map(|n| n.id);
            if nearest.is_some() {
                nearest
            } else {
                let module_id = *synthetic_modules.entry(file_key.clone()).or_insert_with(|| {
                    let id = next_id;
                    next_id = next_id.saturating_add(1);
                    nodes.push(Node {
                        id,
                        kind: NodeKind::Module,
                        symbol: format!("file::{}", file_key),
                        file: file_key.clone(),
                        line: 0,
                        column: 0,
                    });
                    id
                });
                Some(module_id)
            }
        } else {
            function_targets.iter().min_by_key(|n| &n.symbol).map(|n| n.id)
        };

        let block_targets = find_nodes_at_span(&nodes, span, NodeKind::BasicBlock);
        if let Some(dst) = selected_fn {
            edges_added.push(Edge { src: *err_id, dst, kind: EdgeKind::ErrorToFunction });
        }
        if block_targets.is_empty() {
            if let Some(block) = find_nearest_node(&nodes, span, &[NodeKind::BasicBlock]) {
                edges_added.push(Edge { src: *err_id, dst: block.id, kind: EdgeKind::ErrorToBlock });
            }
        } else {
            for block in block_targets {
                edges_added.push(Edge { src: *err_id, dst: block.id, kind: EdgeKind::ErrorToBlock });
            }
        }
    }
    edges.extend(edges_added);

    let (row_ptr, col_idx) = build_csr(nodes.len() as u32, &edges);
    let metadata = Metadata {
        project: output_dir.parent().map(|p| p.display().to_string()).unwrap_or_else(|| output_dir.display().to_string()),
        node_count: nodes.len() as u32,
        edge_count: col_idx.len() as u32,
        generated_by: "UPG extractor".to_string(),
    };
    let id_to_index = nodes.iter().enumerate().map(|(i, n)| (n.id, i)).collect();
    let graph = crate::loader::AnalysisGraph {
        nodes,
        edges,
        row_ptr,
        col_idx,
        repair_surface: Value::Null,
        errors: Value::Null,
        metadata,
        node_kinds: Vec::new(),
        edge_kinds: Vec::new(),
        id_to_index,
    };
    write_outputs(&graph, output_dir)?;

    let surface = compute_repair_surface(&graph);
    write_repair_surface(output_dir, &surface)?;

    Ok(())
}

fn write_outputs(graph: &crate::loader::AnalysisGraph, output_dir: &Path) -> Result<()> {
    fs::create_dir_all(output_dir)?;
    write_nodes_csv(output_dir, &graph.nodes)?;
    write_edges_csv(output_dir, &graph.edges)?;
    write_kinds(output_dir)?;
    write_bin_u32(output_dir.join("csr_row_ptr.bin"), &graph.row_ptr)?;
    write_bin_u32(output_dir.join("csr_col_idx.bin"), &graph.col_idx)?;
    let metadata_path = output_dir.join("metadata.json");
    let file = fs::File::create(metadata_path)?;
    serde_json::to_writer_pretty(file, &graph.metadata)
        .map_err(|err| anyhow!("failed to write metadata.json: {err}"))?;
    Ok(())
}

fn write_nodes_csv(output_dir: &Path, nodes: &[Node]) -> Result<()> {
    let path = output_dir.join("nodes.csv");
    let mut file = fs::File::create(path)?;
    writeln!(file, "node_id,node_kind,symbol,file,line,column")?;
    for node in nodes {
        writeln!(
            file,
            "{},{},{},{},{},{}",
            node.id,
            node_kind_str(node.kind),
            sanitize_csv_field(&node.symbol),
            sanitize_csv_field(&node.file),
            node.line,
            node.column
        )?;
    }
    Ok(())
}

fn write_edges_csv(output_dir: &Path, edges: &[Edge]) -> Result<()> {
    let path = output_dir.join("edges.csv");
    let mut file = fs::File::create(path)?;
    writeln!(file, "src_id,dst_id,edge_kind")?;
    for edge in edges {
        writeln!(file, "{},{},{}", edge.src, edge.dst, edge_kind_str(edge.kind))?;
    }
    Ok(())
}

fn write_bin_u32(path: PathBuf, data: &[u32]) -> Result<()> {
    let mut file = fs::File::create(path)?;
    for &v in data {
        file.write_all(&v.to_le_bytes())?;
    }
    Ok(())
}

pub fn write_repair_surface(output_dir: &Path, surface: &[RepairSurfaceEntry]) -> Result<()> {
    let path = output_dir.join("repair_surface.json");
    let payload = serde_json::json!({
        "top_k": surface,
        "count": surface.len(),
    });
    fs::write(path, serde_json::to_string_pretty(&payload)?)?;
    Ok(())
}

fn compute_repair_surface(graph: &crate::loader::AnalysisGraph) -> Vec<RepairSurfaceEntry> {
    let mut error_to_fn: BTreeMap<u32, u32> = BTreeMap::new();
    for e in &graph.edges {
        if matches!(e.kind, EdgeKind::ErrorToFunction) {
            error_to_fn.insert(e.src, e.dst);
        }
    }
    let mut fn_counts: BTreeMap<u32, usize> = BTreeMap::new();
    for (_, fn_id) in error_to_fn {
        *fn_counts.entry(fn_id).or_insert(0) += 1;
    }

    let mut entries: Vec<RepairSurfaceEntry> = Vec::new();
    for (fn_id, count) in fn_counts {
        if let Some(node) = graph.nodes.iter().find(|n| n.id == fn_id) {
            entries.push(RepairSurfaceEntry {
                node_id: node.id,
                symbol: node.symbol.clone(),
                file: node.file.clone(),
                line: node.line,
                error_count: count,
            });
        }
    }
    entries.sort_by(|a, b| b.error_count.cmp(&a.error_count).then_with(|| a.symbol.cmp(&b.symbol)));
    entries
}

#[derive(Debug, Clone)]
struct ErrorSpan {
    file: String,
    line_start: u32,
    line_end: u32,
    col_start: u32,
    col_end: u32,
}

fn primary_span(err: &Value) -> Option<ErrorSpan> {
    let spans = err.get("spans")?.as_array()?;
    let span = spans.iter().find(|s| s.get("is_primary").and_then(|v| v.as_bool()).unwrap_or(false)).or_else(|| spans.first())?;
    let span = ErrorSpan {
        file: span.get("file_name").and_then(|v| v.as_str()).unwrap_or("unknown").to_string(),
        line_start: span.get("line_start").and_then(|v| v.as_u64()).unwrap_or(0) as u32,
        line_end: span.get("line_end").and_then(|v| v.as_u64()).unwrap_or(0) as u32,
        col_start: span.get("column_start").and_then(|v| v.as_u64()).unwrap_or(0) as u32,
        col_end: span.get("column_end").and_then(|v| v.as_u64()).unwrap_or(0) as u32,
    };
    let _ = span.col_end;
    Some(span)
}

fn find_nodes_at_span<'a>(nodes: &'a [Node], span: &ErrorSpan, kind: NodeKind) -> Vec<&'a Node> {
    let span_file = normalize_file(&span.file);
    nodes
        .iter()
        .filter(|n| n.kind == kind)
        .filter(|n| files_match(&normalize_file(&n.file), &span_file))
        .filter(|n| n.line >= span.line_start && n.line <= span.line_end)
        .collect()
}

fn find_nearest_node<'a>(nodes: &'a [Node], span: &ErrorSpan, kinds: &[NodeKind]) -> Option<&'a Node> {
    let span_file = normalize_file(&span.file);
    let mut candidates: Vec<&Node> = nodes
        .iter()
        .filter(|n| kinds.contains(&n.kind))
        .filter(|n| files_match(&normalize_file(&n.file), &span_file))
        .collect();
    if candidates.is_empty() {
        return None;
    }
    candidates.sort_by_key(|n| {
        let line = n.line as i64;
        let target = span.line_start as i64;
        let diff = if line <= target { target - line } else { line - target + 1_000_000 };
        diff
    });
    candidates.first().copied()
}

fn files_match(node_file: &str, span_file: &str) -> bool {
    if node_file == span_file {
        return true;
    }
    node_file.ends_with(span_file) || span_file.ends_with(node_file)
}

fn normalize_file(file: &str) -> String {
    if let Some(idx) = file.find("embeddable_name: \"") {
        let start = idx + "embeddable_name: \"".len();
        if let Some(end) = file[start..].find('"') {
            return file[start..start + end].to_string();
        }
    }
    if let Some(idx) = file.find("name: \"") {
        let start = idx + "name: \"".len();
        if let Some(end) = file[start..].find('"') {
            return file[start..start + end].to_string();
        }
    }
    file.to_string()
}

fn read_nodes_csv(path: PathBuf) -> Result<Vec<Node>> {
    let content = fs::read_to_string(path)?;
    let mut nodes = Vec::new();
    for (idx, line) in content.lines().enumerate() {
        if idx == 0 || line.trim().is_empty() {
            continue;
        }
        let parts: Vec<&str> = line.split(',').collect();
        if parts.len() < 6 {
            return Err(anyhow!("invalid nodes.csv line"));
        }
        let id = parts[0].parse::<u32>()?;
        let kind = parse_node_kind(parts[1])?;
        let line_no = parts[parts.len() - 2].parse::<u32>()?;
        let col = parts[parts.len() - 1].parse::<u32>()?;
        let file = parts[parts.len() - 3].to_string();
        let symbol = parts[2..parts.len() - 3].join(",");
        nodes.push(Node {
            id,
            kind,
            symbol,
            file,
            line: line_no,
            column: col,
        });
    }
    Ok(nodes)
}

fn read_edges_csv(path: PathBuf) -> Result<Vec<Edge>> {
    let content = fs::read_to_string(path)?;
    let mut edges = Vec::new();
    for (idx, line) in content.lines().enumerate() {
        if idx == 0 || line.trim().is_empty() {
            continue;
        }
        let parts: Vec<&str> = line.split(',').collect();
        if parts.len() < 3 {
            return Err(anyhow!("invalid edges.csv line"));
        }
        let src = parts[0].parse::<u32>()?;
        let dst = parts[1].parse::<u32>()?;
        let kind = parse_edge_kind(parts[2])?;
        edges.push(Edge { src, dst, kind });
    }
    Ok(edges)
}

fn build_csr(node_count: u32, edges: &[Edge]) -> (Vec<u32>, Vec<u32>) {
    let mut adj: Vec<Vec<u32>> = vec![Vec::new(); node_count as usize];
    for e in edges {
        if (e.src as usize) < adj.len() {
            adj[e.src as usize].push(e.dst);
        }
    }
    let mut row_ptr = Vec::with_capacity(adj.len() + 1);
    let mut col_idx = Vec::new();
    row_ptr.push(0u32);
    for neighbors in adj {
        for v in neighbors {
            col_idx.push(v);
        }
        row_ptr.push(col_idx.len() as u32);
    }
    (row_ptr, col_idx)
}

fn node_kind_str(kind: NodeKind) -> &'static str {
    match kind {
        NodeKind::Function => "FUNCTION",
        NodeKind::Method => "METHOD",
        NodeKind::Struct => "STRUCT",
        NodeKind::Enum => "ENUM",
        NodeKind::Trait => "TRAIT",
        NodeKind::Impl => "IMPL",
        NodeKind::Field => "FIELD",
        NodeKind::Param => "PARAM",
        NodeKind::Variable => "VARIABLE",
        NodeKind::Module => "MODULE",
        NodeKind::Type => "TYPE",
        NodeKind::BasicBlock => "BASIC_BLOCK",
        NodeKind::CallSite => "CALL_SITE",
        NodeKind::Error => "ERROR",
    }
}

fn edge_kind_str(kind: EdgeKind) -> &'static str {
    match kind {
        EdgeKind::HasField => "HAS_FIELD",
        EdgeKind::HasMethod => "HAS_METHOD",
        EdgeKind::HasBlock => "HAS_BLOCK",
        EdgeKind::HasParam => "HAS_PARAM",
        EdgeKind::Imports => "IMPORTS",
        EdgeKind::Flow => "FLOW",
        EdgeKind::Call => "CALL",
        EdgeKind::Return => "RETURN",
        EdgeKind::Unwind => "UNWIND",
        EdgeKind::Implements => "IMPLEMENTS",
        EdgeKind::UsesType => "USES_TYPE",
        EdgeKind::Bounds => "BOUNDS",
        EdgeKind::Assign => "ASSIGN",
        EdgeKind::Propagates => "PROPAGATES",
        EdgeKind::ArgToParam => "ARG_TO_PARAM",
        EdgeKind::Returns => "RETURNS",
        EdgeKind::ErrorToFunction => "ERROR_TO_FUNCTION",
        EdgeKind::ErrorToBlock => "ERROR_TO_BLOCK",
    }
}

fn parse_node_kind(raw: &str) -> Result<NodeKind> {
    match raw {
        "FUNCTION" => Ok(NodeKind::Function),
        "METHOD" => Ok(NodeKind::Method),
        "STRUCT" => Ok(NodeKind::Struct),
        "ENUM" => Ok(NodeKind::Enum),
        "TRAIT" => Ok(NodeKind::Trait),
        "IMPL" => Ok(NodeKind::Impl),
        "FIELD" => Ok(NodeKind::Field),
        "PARAM" => Ok(NodeKind::Param),
        "VARIABLE" => Ok(NodeKind::Variable),
        "MODULE" => Ok(NodeKind::Module),
        "TYPE" => Ok(NodeKind::Type),
        "BASIC_BLOCK" => Ok(NodeKind::BasicBlock),
        "CALL_SITE" => Ok(NodeKind::CallSite),
        "ERROR" => Ok(NodeKind::Error),
        _ => Err(anyhow!("unknown node kind")),
    }
}

fn parse_edge_kind(raw: &str) -> Result<EdgeKind> {
    match raw {
        "HAS_FIELD" => Ok(EdgeKind::HasField),
        "HAS_METHOD" => Ok(EdgeKind::HasMethod),
        "HAS_BLOCK" => Ok(EdgeKind::HasBlock),
        "HAS_PARAM" => Ok(EdgeKind::HasParam),
        "IMPORTS" => Ok(EdgeKind::Imports),
        "FLOW" => Ok(EdgeKind::Flow),
        "CALL" => Ok(EdgeKind::Call),
        "RETURN" => Ok(EdgeKind::Return),
        "UNWIND" => Ok(EdgeKind::Unwind),
        "IMPLEMENTS" => Ok(EdgeKind::Implements),
        "USES_TYPE" => Ok(EdgeKind::UsesType),
        "BOUNDS" => Ok(EdgeKind::Bounds),
        "ASSIGN" => Ok(EdgeKind::Assign),
        "PROPAGATES" => Ok(EdgeKind::Propagates),
        "ARG_TO_PARAM" => Ok(EdgeKind::ArgToParam),
        "RETURNS" => Ok(EdgeKind::Returns),
        "ERROR_TO_FUNCTION" => Ok(EdgeKind::ErrorToFunction),
        "ERROR_TO_BLOCK" => Ok(EdgeKind::ErrorToBlock),
        _ => Err(anyhow!("unknown edge kind")),
    }
}

fn sanitize_csv_field(raw: &str) -> String {
    let mut out = raw.replace('\n', " ").replace('\r', " ");
    if out.contains(',') {
        out = out.replace(',', ";");
    }
    out
}

fn write_kinds(output_dir: &Path) -> Result<()> {
    let node_kinds = [
        "FUNCTION",
        "METHOD",
        "STRUCT",
        "ENUM",
        "TRAIT",
        "IMPL",
        "FIELD",
        "PARAM",
        "VARIABLE",
        "MODULE",
        "TYPE",
        "BASIC_BLOCK",
        "CALL_SITE",
        "ERROR",
    ];
    let edge_kinds = [
        "HAS_FIELD",
        "HAS_METHOD",
        "HAS_BLOCK",
        "HAS_PARAM",
        "IMPORTS",
        "FLOW",
        "CALL",
        "RETURN",
        "UNWIND",
        "IMPLEMENTS",
        "USES_TYPE",
        "BOUNDS",
        "ASSIGN",
        "PROPAGATES",
        "ARG_TO_PARAM",
        "RETURNS",
        "ERROR_TO_FUNCTION",
        "ERROR_TO_BLOCK",
    ];
    fs::write(output_dir.join("node_kinds.txt"), node_kinds.join("\n"))?;
    fs::write(output_dir.join("edge_kinds.txt"), edge_kinds.join("\n"))?;
    Ok(())
}
